static char grid[100][102];
static int dist[10000], queue[10000];

int main(void) {
    int rows, cols;
    if (scanf("%d %d", &rows, &cols) != 2 || rows < 1 || rows > 100 || cols < 1 || cols > 100) {
        return 0;
    }
    int source = -1, target = -1;
    for (int r = 0; r < rows; r++) {
        scanf("%101s", grid[r]);
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 'S') {
                source = r * cols + c;
            } else if (grid[r][c] == 'E') {
                target = r * cols + c;
            }
        }
    }
    for (int i = 0; i < rows * cols; i++) {
        dist[i] = -1;
    }
    int head = 0, tail = 0;
    dist[source] = 0;
    queue[tail++] = source;
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    while (head < tail) {
        int u = queue[head++];
        for (int d = 0; d < 4; d++) {
            int r = u / cols + dr[d], c = u % cols + dc[d];
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                continue;
            }
            int v = r * cols + c;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[tail++] = v;
            }
        }
    }
    printf("%d\n", dist[target]);
    return 0;
}

